      {lyric:'E nas fraquezas está comigo, / Ele só, Ele só.',anchors:[{pos:0,chord:'F'},{pos:9,chord:'F/A'},{pos:18,chord:'Bb'},{pos:24,chord:'F'},{pos:35,chord:'C'},{pos:43,chord:'F'}]}
