      {lyric:'E pelos Seus santos sempre vela, / Ele só, Ele só.',anchors:[{pos:0,chord:'F'},{pos:8,chord:'F/A'},{pos:21,chord:'Bb'},{pos:28,chord:'F'},{pos:39,chord:'C'},{pos:47,chord:'F'}]}
