      {lyric:'Cristo, que é teu amado Pastor, / Tomará conta de ti.',anchors:[{pos:1,chord:'Bb'},{pos:11,chord:'Eb'},{pos:19,chord:'Bb'},{pos:34,chord:'F'},{pos:49,chord:'Bb'}]}
