      {lyric:'Cristo, que nos dá poder e valor, / Tomará conta de ti.',anchors:[{pos:1,chord:'Bb'},{pos:12,chord:'Eb'},{pos:21,chord:'Bb'},{pos:36,chord:'F'},{pos:51,chord:'Bb'}]}
