      {lyric:'Que a formosa luz de Deus fulgure em ti, / E serás feliz assim.',anchors:[{pos:0,chord:'Ab'},{pos:29,chord:'Db'},{pos:42,chord:'Eb'},{pos:59,chord:'Ab'}]}
