      {lyric:'E nossa fé terá valor;',anchors:[{pos:1,chord:'Ab'},{pos:7,chord:'Db'},{pos:18,chord:'Ab'}]},
      {lyric:'Nós dizemos: “Ora, vem Senhor Jesus”.',anchors:[{pos:5,chord:'Db'},{pos:19,chord:'Eb'},{pos:32,chord:'Ab'}]}
