      {lyric:'Estais lavados - E libertados,',anchors:[{pos:9,chord:'Eb'}]},
      {lyric:'No nome santo de Jesus!',anchors:[{pos:8,chord:'Ab'},{pos:14,chord:'Bb'},{pos:19,chord:'Eb'}]}
