      {lyric:'P’ra que tudo, que tens dito, / Cumpra-se, meu Redentor.',anchors:[{pos:9,chord:'F'},{pos:24,chord:'C'},{pos:39,chord:'F'},{pos:48,chord:'C'},{pos:53,chord:'F'}]}
